    var PCT = { page:3, load:6, client:10, unpack:42, assets:48, init:66, start:72, title:95, done:100 };
    var LABEL = { page:"Loading Treasure Client", load:"Loading Treasure Client", client:"Downloading the game", unpack:"Unpacking the game", assets:"Loading resources", init:"Starting the engine", start:"Building block textures and models", title:"Opening the title screen", done:"Ready!" };
