+ "filter:drop-shadow(0 2px 10px rgba(255,190,60,.25))}"
+ "#tc-boot .tcb-title span{display:block;margin-top:2px;font-size:13px;letter-spacing:.62em;padding-left:.62em;text-align:center;font-family:'Outfit',system-ui,sans-serif;font-weight:600}"
+ "#tc-boot .tcb-bar{position:relative;margin-top:30px;width:320px;max-width:78vw;height:12px;border-radius:999px;overflow:hidden;"
+ "background:rgba(255,214,120,.08);border:1px solid rgba(255,214,120,.26);box-shadow:0 0 18px rgba(0,0,0,.5) inset}"
+ "#tc-boot .tcb-fill{position:absolute;inset:0;transform-origin:0 50%;transform:scaleX(0);border-radius:999px;overflow:hidden;"
+ "background:linear-gradient(90deg,#a8701c,#ffd76b 70%,#fff3c4);box-shadow:0 0 14px rgba(255,205,90,.6);will-change:transform}"
+ "#tc-boot .tcb-shine{position:absolute;top:0;bottom:0;left:0;width:40%;background:linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,.55),rgba(255,255,255,0));"
+ "animation:tcbShine 1.7s ease-in-out infinite;will-change:transform}"
