+ "#tc-boot .tcb-pct{color:#ffd76b;font-weight:600}"
+ "#tc-boot .tcb-prompt{margin-top:22px;font:600 16px 'Outfit',system-ui,sans-serif;color:#fff3c4;letter-spacing:.04em;opacity:0;transform:translateY(6px);transition:opacity .3s,transform .3s}"
+ "#tc-boot.tcb-wait .tcb-prompt{opacity:1;transform:none;animation:tcbBlink 1.6s ease-in-out infinite}"
+ "#tc-boot .tcb-tip{margin-top:18px;min-height:18px;max-width:80vw;text-align:center;font:400 13px 'Outfit',system-ui,sans-serif;color:#a8936a;transition:opacity .4s ease}"
+ "#tc-boot.tcb-wait .tcb-tip{opacity:0}"
+ "#tc-boot .tcb-tip.tcb-fade{opacity:0}"
